function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 10000) return 's needs 1 to 10^4 characters.';
  if (!/^[0-9+\-*\/()]+$/.test(s)) return 's may contain only digits, + - * / and parentheses (no spaces).';
  const MIN = -(2 ** 31), MAX = 2 ** 31 - 1;
  const rank = { '+': 1, '-': 1, '*': 2, '/': 2 };
  const values = [], ops = [];
  let problem = null;
  const reduce = () => {
    const b = values.pop(), a = values.pop(), op = ops.pop();
    if (op === '/' && b === 0) { problem = 'The expression must not divide by zero.'; return; }
    const v = op === '+' ? a + b : op === '-' ? a - b : op === '*' ? a * b : Math.trunc(a / b);
    if (v < MIN || v > MAX) problem = 'Every intermediate result must fit in a signed 32-bit integer.';
    values.push(v);
  };
  let expectOperand = true;
  for (let i = 0; i < s.length && !problem; i++) {
    const ch = s[i];
    if (ch >= '0' && ch <= '9') {
      if (!expectOperand) return 'A number cannot directly follow a closing parenthesis.';
      let n = 0;
      while (i < s.length && s[i] >= '0' && s[i] <= '9') n = n * 10 + Number(s[i++]);
      i--;
      if (n > MAX) return 'Every number must fit in a signed 32-bit integer.';
      values.push(n);
      expectOperand = false;
    } else if (ch === '(') {
      if (!expectOperand) return 'An opening parenthesis must follow an operator or another opening parenthesis.';
      ops.push('(');
    } else if (ch === ')') {
      if (expectOperand) return 'A closing parenthesis must follow a number or another closing parenthesis.';
      while (ops.length && ops[ops.length - 1] !== '(' && !problem) reduce();
      if (!ops.length) return 'The parentheses are not balanced.';
      ops.pop();
    } else {
      if (expectOperand) return 'Each operator needs an operand on both sides (no unary minus).';
      while (ops.length && ops[ops.length - 1] !== '(' && rank[ops[ops.length - 1]] >= rank[ch] && !problem) reduce();
      ops.push(ch);
      expectOperand = true;
    }
  }
  if (problem) return problem;
  if (expectOperand) return 'The expression cannot end with an operator or an opening parenthesis.';
  while (ops.length && !problem) {
    if (ops[ops.length - 1] === '(') return 'The parentheses are not balanced.';
    reduce();
  }
  return problem;
}

