function generate(rand, size) {
  const MAX = 2 ** 31 - 1;
  const large = size === 'large';
  const maxDepth = large ? 22 : 4;
  const leaf = () => {
    const r = rand();
    const value = r < 0.6 ? Math.floor(rand() * 10) : r < 0.92 ? Math.floor(rand() * 1000) : Math.floor(rand() * (MAX + 1));
