    const left = build(split, depth + 1);
    const right = build(leaves - split, depth + 1);
    for (const op of ['+-*/'[Math.floor(rand() * 4)], '+', '-']) {
      const value = apply(op, left.value, right.value);
      if (value === null || value < -MAX || value > MAX) continue;
